const uint8_t* ascii_rows(uint32_t cp) {
  if (cp < 0x20 || cp > 0x7E) return nullptr;
  return kAsciiBits[cp - 0x20];
}

int ascii_advance(uint32_t cp) {
  if (cp < 0x20 || cp > 0x7E) return 0;
  return kAsciiAdvance[cp - 0x20];
}

